#include "rpg/pve_visual.hpp"
#include "rpg/battle_presentation.hpp"
#include <iostream>
#include <stdexcept>
using namespace rpg;
using namespace rpg::presentation;
void check(bool x,const char* message){if(!x){throw std::runtime_error(message);}}
void fixture(){PveVisualSession s;const auto v=s.state();check(v.combat.profile==CombatProfile::Team&&v.combat.battle.fighters.size()==3&&v.abilities.size()==3,"ritual team profile");const auto h=pve_hud(s.observation());check(h.boss_id=="ECO-1"&&h.commands_open&&!h.score,"ritual goal, no reward");check(v.combat.battle.rules.combat_model==team_reference_rules().combat_model,"shared funnel");}
void passive(){PveVisualSession s;const auto before=s.observation();check(s.submit(0,2,"ECO-1").error==VisualError::CoreRejected&&s.observation()==before&&s.state().revision==0,"passive cannot be selected");check(ability_card(s.state(),2).badge==AbilityBadge::Passive,"passive information preserved");}
void slots(){PveVisualSession s;auto first=s.submit(0,3,"ECO-1");check(first.accepted(),"A3 routed through PvE");auto v=s.state();check(v.revision==1&&s.observation().battle.accepted_actions==1,"one action only");for(int i=0;i<10&&v.automatic;++i){check(s.step_automatic().accepted(),"enemy automation");v=s.state();}check(!v.automatic&&!s.finished(),"player regained opportunity");check(ability_card(v,3).badge==AbilityBadge::Cooldown,"A3 cooldown real");check(s.submit(v.revision,1,"ECO-1").accepted(),"A1 remains usable");}
void stale(){PveVisualSession s;check(s.submit(0,1,"ECO-1").accepted(),"opening A1");const auto before=s.observation();check(s.submit(0,1,"ECO-1").error==VisualError::StaleCommand&&s.observation()==before,"stale commands atomic");check(s.submit(1,1,"ECO-1").error==VisualError::NotPlayerTurn,"enemy turn protected");}
void bad_target(){PveVisualSession s;const auto before=s.observation();check(!s.submit(0,1,"FELIPE").accepted()&&s.observation()==before,"enemy-only A1");check(!s.submit(0,9,"ECO-1").accepted()&&s.observation()==before,"unknown slot");}
void goal(){auto d=ritual_lab_definition();d.roster[1].max_health=1;d.roster[1].stats.block=0;PveVisualSession s(d);check(s.submit(0,1,"ECO-1").accepted()&&s.finished(),"kill declared boss");auto observation=s.observation();const auto auxiliary=std::ranges::find(observation.battle.fighters,std::string("ECO-2"),[](const Fighter& f){return f.definition.id;});check(observation.objective_met&&auxiliary!=observation.battle.fighters.end()&&auxiliary->health>0,"auxiliary alive does not prevent ritual win");check(s.submit(1,1,"ECO-2").error==VisualError::Finished&&s.observation()==observation,"no actions after objective");check(s.state().progress.credits==0&&s.state().progress.completions.empty(),"ritual cannot grant generic credits");}
void reset(){PveVisualSession s;const auto old=s.observation().attempt_id;s.reset();check(s.observation().attempt_id!=old&&s.state().revision==1&&s.state().progress.attempt==2,"fresh attempt identity");check(s.submit(0,1,"ECO-1").error==VisualError::StaleCommand,"reset invalidates old input");}
void abandon(){PveVisualSession s;const auto before=s.observation();s.abandon();check(s.submit(0,1,"ECO-1").error==VisualError::SafetyStop&&s.observation()==before,"abandon no damage/reward");s.reset();check(s.submit(s.state().revision,1,"ECO-1").accepted(),"fresh ritual after abandon");}
void move_and_isolation(){VisualSession reference(terminal_lab_setup()),pilot(felipe_pilot_setup());const auto a=reference.state(),b=pilot.state();PveVisualSession original;PveVisualSession moved(std::move(original));check(moved.submit(0,1,"ECO-1").accepted(),"moved ledger remains valid");check(reference.state().combat==a.combat&&pilot.state().combat==b.combat,"other labs untouched");}
void complete(){PveVisualSession s;for(int i=0;i<250&&!s.finished();++i){const auto v=s.state();if(v.automatic){check(s.step_automatic().accepted(),"full ritual enemy");}else{check(s.submit(v.revision,1,"ECO-1").accepted(),"full ritual player");}}check(s.finished()&&s.observation().objective_met,"ritual playable to completion");}
void opening(){auto setup=terminal_lab_setup();PveDefinition d;d.id="opening";d.attempt_id="opening-1";d.boss_id="B1";d.roster=setup.roster;d.rules=setup.rules;d.loadouts=setup.loadouts;ScoreLedger ledger;PveEncounter encounter(d,ledger);check(has_status(*encounter.battle().find("A2"),EffectKind::Shield),"opening passive is initialized once by profile");auto views=encounter.abilities("A3");check(views[2].availability==AbilityAvailability::ConditionBlocked,"shared condition respected");}
void slots_match(){auto setup=felipe_pilot_setup();ProfileBattle normal(setup.roster,setup.rules,CombatProfile::Team,setup.loadouts);PveVisualSession ritual;const auto normalAction=normal.apply_slot(1,"ECO-1");const auto ritualAction=ritual.submit(0,1,"ECO-1");check(normalAction.accepted()&&ritualAction.accepted(),"same base action");const auto snapshot=ritual.state();const auto target=std::ranges::find(snapshot.combat.battle.fighters,std::string("ECO-1"),[](const Fighter& f){return f.definition.id;});if(target==snapshot.combat.battle.fighters.end()){throw std::runtime_error("missing ritual target");}if(normal.battle().find("ECO-1")->health!=target->health){std::cerr<<"normal="<<normal.battle().find("ECO-1")->health<<" ritual="<<target->health<<"\n";}check(normal.battle().find("ECO-1")->health==target->health,"same hit calculation and RNG seed");}
int main(){try{fixture();passive();slots();stale();bad_target();goal();reset();abandon();move_and_isolation();complete();opening();slots_match();std::cout<<"REG_RITUAL_TESTS_RESULT passed=12 total=12\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}